    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder().appName("CacheHitRate").master("local[*]").getOrCreate();
        JavaRDD<String> onsiteAttributedData = spark.sparkContext.parallelize(
                List.of("query1,1678886400", "query2,1678886401", "query1,1678886402", "query3,1678886403",
