        JavaRDD<String> topFrequentQueries = spark.sparkContext.parallelize(List.of("query1", "query2"));

        // Convert topFrequentQueries to a Set for efficient lookup
        Set<String> topQueriesSet = topFrequentQueries.collectAsMap().keySet();

        // Cache
        Map<String, Long> cache = new HashMap<>();

        // Cache TTL in seconds (12 hours)
        long cacheTTL = 12 * 60 * 60;

        // Hit/Miss counters
        long cacheHits = 0;
        long cacheMisses = 0;

        // Process each record in onsiteAttributedData
        onsiteAttributedData.foreach(record -> {
            String[] parts = record.split(",");
            String query = parts[0];
            long timestamp = Long.parseLong(parts[1]);

            if (topQueriesSet.contains(query)) {
                if (!cache.containsKey(query)) {
                    // Cache miss
                    cacheMisses++;
                    // Simulate fetching the query from external source
                    System.out.println("Cache miss for query: " + query + ", fetching from external source...");

                    // Add query to cache with TTL
                    cache.put(query, timestamp + cacheTTL);
                } else {
                    // Cache hit
                    if (cache.get(query) > timestamp) {
                        cacheHits++;
                        System.out.println("Cache hit for query: " + query);
                    } else {
                        // Cache expired, treat as miss
                        cacheMisses++;
                        System.out.println("Cache expired for query: " + query + ", treating as miss...");
                        cache.put(query, timestamp + cacheTTL);
                    }
                }
            }
        });

        // Calculate hit rate
        double hitRate = (double) cacheHits / (cacheHits + cacheMisses);

        System.out.println("Cache Hits: " + cacheHits);
        System.out.println("Cache Misses: " + cacheMisses);
        System.out.println("Cache Hit Rate: " + hitRate);

        spark.stop();
    }
}
