```javascript
const table = document.querySelector('.table');
let sortColumn = null;
let sortOrder = 1; // 1 for ascending, -1 for descending

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const column = event.target.dataset.sort;

    if (column === sortColumn) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = column;
      sortOrder = 1;
    }

    sortTable(sortColumn, sortOrder);
  }
});

function sortTable(column, order) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.querySelectorAll('td')[getColumnIndex(column)];
    const cellB = b.querySelectorAll('td')[getColumnIndex(column)];

    let valueA = cellA.textContent;
    let valueB = cellB.textContent;

    switch (column) {
      case 'string':
        valueA = valueA.toLowerCase();
        valueB = valueB.toLowerCase();
        break;
      case 'number':
        valueA = parseFloat(valueA);
        valueB = parseFloat(valueB);
        break;
      case 'date':
        valueA = new Date(valueA);
        valueB = new Date(valueB);
        break;
    }

    if (valueA < valueB) {
      return -1 * order;
    }
    if (valueA > valueB) {
      return 1 * order;
    }
    return 0;
  });

  // Clear the table body and re-append sorted rows
  table.querySelector('tbody').innerHTML = '';
  rows.forEach(row => table.querySelector('tbody').appendChild(row));
}

function getColumnIndex(column) {
    const headers = Array.from(table.querySelectorAll('th'));
    for (let i = 0; i < headers.length; i++) {
        if (headers[i].dataset.sort === column) {
            return i;
        }
    }
    return -1; // Should not happen if data-sort is correct
}
