/**
 * Packs an array of entities into an ArrayBuffer.
 *
 * @param {Array<Object>} entities An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 * @returns {ArrayBuffer} An ArrayBuffer containing the packed entities.
 * @throws {Error} If any entity has an invalid 'id' or 'size' value.
 */
function packEntities(entities) {
  const totalBits = entities.length * 7; // 4 bits for id + 3 bits for size = 7 bits per entity
  const buffer = new ArrayBuffer(Math.ceil(totalBits / 8));
  const dataView = new DataView(buffer);
  let bitOffset = 0;

  for (const entity of entities) {
    const id = entity.id;
    const size = entity.size;

    if (id < 0 || id > 15) {
      throw new Error("Invalid entity id: " + id + ". Id must be between 0 and 15.");
    }
    if (size < 0 || size > 7) {
      throw new Error("Invalid entity size: " + size + ". Size must be between 0 and 7.");
    }

    // Pack id (4 bits)
    dataView.setUint8(0, (dataView.getUint8(0) | (id << (7 - bitOffset))) & 0xFF);
    bitOffset++;

    // Pack size (3 bits)
    dataView.setUint8(0, (dataView.getUint8(0) | (size << (7 - bitOffset))) & 0xFF);
    bitOffset++;

    if (bitOffset === 8) {
      bitOffset = 0;
    }
  }

  return buffer;
}

/**
 * Unpacks an ArrayBuffer containing packed entities into an array of entities.
 *
 * @param {ArrayBuffer} buffer An ArrayBuffer containing the packed entities.
 * @returns {Array<Object>} An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 */
function unpackEntities(buffer) {
  const dataView = new DataView(buffer);
  const entities = [];
  let bitOffset = 0;
  let byteOffset = 0;

  while (byteOffset < buffer.byteLength) {
    let byte = dataView.getUint8(byteOffset);
    let id = (byte >> (7 - bitOffset)) & 0xF; // Extract 4 bits for id
    let size = (byte >> (7 - bitOffset - 4)) & 0x7; // Extract 3 bits for size

    entities.push({ id: id, size: size });

    bitOffset += 7;
    if (bitOffset === 8) {
      bitOffset = 0;
      byteOffset++;
    } else {
      byteOffset++;
    }
  }

  return entities;
}
