export default class CsvDownloaderComponent extends Component {
  @service router;

  url = '';
  downloading = false;
  error = null;
  progress = 0;

  constructor() {
    super(...arguments);
  }

  @action
  startDownload() {
    this.error = null;
    this.downloading = true;
    this.progress = 0;

    const worker = new Worker(this.router.generate('csv-worker', {})); // Assuming you have a route for the worker

    worker.onmessage = (event) => {
      const { type, data } = event.data;

      if (type === 'progress') {
        this.progress = data;
      } else if (type === 'success') {
        const blob = new Blob([data], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'data.csv'; // You can customize the filename
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        this.downloading = false;
      } else if (type === 'error') {
        this.error = data;
        this.downloading = false;
      }
    };

    worker.onerror = (error) => {
      this.error = 'Worker error: ' + error.message;
      this.downloading = false;
    };

    worker.postMessage({ url: this.url });
  }

  @action
  updateUrl(event) {
    this.url = event.target.value;
